import java.util.Scanner;

class Rectangle {
    int width;
    int height;

    int area() {
        return width * height;
    }

    boolean isSquare() {
        return width == height;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        Rectangle r1 = new Rectangle();
        r1.width = sc.nextInt();
        r1.height = sc.nextInt();

        Rectangle r2 = new Rectangle();
        r2.width = sc.nextInt();
        r2.height = sc.nextInt();

        System.out.println("1つ目 面積" + r1.area() + " 正方形" + r1.isSquare());
