import java.util.Scanner;

class Item {
    static int created;
    static int totalPrice;
    int price;

    Item(int price) {
        this.price = price;
        created++;
        totalPrice += price;
    }

    static double average() {
        if (created == 0) {
            return 0.0;
        }
        return (double) totalPrice / created;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        for (int i = 0; i < n; i++) {
            new Item(sc.nextInt());
        }

        System.out.println("作った数 " + Item.created);
        System.out.println("合計 " + Item.totalPrice);
        System.out.println("平均 " + Item.average());
    }
}

